package org.dromara.title.service;

import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.common.satoken.utils.LoginHelper;
import org.dromara.title.domain.*;
import org.dromara.title.mapper.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.*;

@Service @RequiredArgsConstructor
public class TitleEvaluationService {
 private final TitleApplicationMapper applications; private final TitleVersionMapper versions; private final TitleReviewMapper reviews; private final TitleAuditMapper audits; private final ObjectMapper json;
 @Transactional public TitleApplication createDraft(Long batchId, Map<String,Object> form) { Long user=actor(); if (applications.exists(Wrappers.<TitleApplication>lambdaQuery().eq(TitleApplication::getBatchId,batchId).eq(TitleApplication::getApplicantUserId,user).notIn(TitleApplication::getStatus,List.of("REJECTED","ARCHIVED")))) throw new IllegalStateException("同一人员同一批次只允许一条有效申报"); TitleApplication a=new TitleApplication(); a.setBatchId(batchId);a.setApplicantUserId(user);a.setStatus("DRAFT");a.setCurrentVersion(0);a.setFormJson(write(form));a.setCreatedAt(LocalDateTime.now());applications.insert(a);audit(a,"CREATE_DRAFT",null,"DRAFT","创建草稿");return a; }
 @Transactional public TitleApplication saveDraft(Long id,Map<String,Object> form){ TitleApplication a=get(id); allow(a,"DRAFT","CORRECTION_REQUIRED"); Map<String,Object> merged=read(a.getFormJson());merged.putAll(form);a.setFormJson(write(merged));applications.updateById(a);audit(a,"SAVE_DRAFT",a.getStatus(),a.getStatus(),"保存草稿");return a; }
 @Transactional public TitleApplication submit(Long id){ TitleApplication a=get(id);allow(a,"DRAFT","CORRECTION_REQUIRED");String before=a.getStatus();a.setCurrentVersion(a.getCurrentVersion()+1);a.setStatus("PENDING_DEPARTMENT_REVIEW");TitleApplicationVersion v=new TitleApplicationVersion();v.setApplicationId(id);v.setVersionNo(a.getCurrentVersion());v.setFormSnapshot(a.getFormJson());v.setMaterialSnapshot("[]");v.setPrecheckSnapshot("{}");v.setSubmittedAt(LocalDateTime.now());versions.insert(v);applications.updateById(a);audit(a,"SUBMIT_V"+a.getCurrentVersion(),before,a.getStatus(),"提交版本快照");return a; }
 @Transactional public TitleApplication review(Long id,String action,String reason,Long correctionHours){ TitleApplication a=get(id);Long user=actor();if(a.getApplicantUserId().equals(user))throw new IllegalStateException("申请人不得审核本人申报");String before=a.getStatus();if("approve".equals(action))a.setStatus(next(before));else if("return".equals(action)){a.setStatus("CORRECTION_REQUIRED");a.setCorrectionDeadline(LocalDateTime.now().plusHours(correctionHours==null?72:correctionHours));}else if("reject".equals(action)){if(reason==null||reason.isBlank())throw new IllegalStateException("驳回必须填写依据");a.setStatus("REJECTED");}else throw new IllegalArgumentException("未知审核动作");TitleReviewRecord r=new TitleReviewRecord();r.setApplicationId(id);r.setVersionNo(a.getCurrentVersion());r.setReviewerUserId(user);r.setReviewNode(before);r.setAction(action);r.setReason(reason);r.setCreatedAt(LocalDateTime.now());reviews.insert(r);applications.updateById(a);audit(a,"REVIEW_"+action.toUpperCase(),before,a.getStatus(),reason);return a; }
 public TitleApplication get(Long id){TitleApplication a=applications.selectById(id);if(a==null)throw new NoSuchElementException("申报不存在");return a;} public List<TitleAuditEvent> auditEvents(Long id){return audits.selectList(Wrappers.<TitleAuditEvent>lambdaQuery().eq(TitleAuditEvent::getApplicationId,id).orderByAsc(TitleAuditEvent::getOccurredAt));}
 private void audit(TitleApplication a,String event,String before,String after,String reason){TitleAuditEvent e=new TitleAuditEvent();e.setApplicationId(a.getId());e.setActorUserId(actor());e.setEventType(event);e.setBeforeStatus(before);e.setAfterStatus(after);e.setVersionNo(a.getCurrentVersion());e.setReason(reason);e.setOccurredAt(LocalDateTime.now());audits.insert(e);} private Long actor(){Long id=LoginHelper.getUserId();if(id==null)throw new IllegalStateException("请先登录");return id;} private static void allow(TitleApplication a,String... s){if(!List.of(s).contains(a.getStatus()))throw new IllegalStateException("当前状态不允许操作");} private static String next(String s){return switch(s){case "PENDING_DEPARTMENT_REVIEW"->"PENDING_TECHNICAL_REVIEW";case "PENDING_TECHNICAL_REVIEW"->"PENDING_DEPARTMENT_LEADER_REVIEW";case "PENDING_DEPARTMENT_LEADER_REVIEW"->"PENDING_HR_REVIEW";case "PENDING_HR_REVIEW"->"APPROVED";default->throw new IllegalStateException("当前状态不能通过");};} private Map<String,Object> read(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){return new LinkedHashMap<>();}} private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException("JSON序列化失败",e);}}
}
